// GetSecretsProjectsResponse is the answer to GetSecretsProjects.
type GetSecretsProjectsResponse struct {
	Response
	JSON200 *struct {
		ProjectWarnings struct {
			// Limit The maximum number of projects to return per page.
			Limit int `json:"limit"`

			// Offset The number of projects to skip before returning results.
			Offset   int `json:"offset"`
			Projects []struct {
				// ProjectId The ID of the project.
				ProjectId string `json:"projectId"`

				// ProjectName The name of the project.
				ProjectName string `json:"projectName"`

				// ProjectSlug The slug of the project.
				ProjectSlug string `json:"projectSlug"`

				// SeverityScore A relative score used to rank projects by the severity of their outstanding issues. The scoring heuristic may change over time.
				SeverityScore int `json:"severityScore"`

				// TotalSecrets The total number of shared secrets in the project.
				TotalSecrets int `json:"totalSecrets"`

				// Warnings The counts of outstanding issues detected in the project.
				Warnings struct {
					// DuplicatedSecrets The number of secrets in the project whose value is shared with at least one other secret in the same project. Secrets whose value is a reference to another secret are counted as duplicates. Null when the project does not have secret blind indexing enabled.
					DuplicatedSecrets *int `json:"duplicatedSecrets"`

					// FailedRotations The number of secret rotations in the project whose last rotation attempt failed.
					FailedRotations int `json:"failedRotations"`

					// FailedSyncs The number of secret syncs in the project whose last sync attempt failed.
					FailedSyncs int `json:"failedSyncs"`

					// OrphanedLeases The number of dynamic secret leases in the project that failed to be revoked and require manual cleanup.
					OrphanedLeases int `json:"orphanedLeases"`

					// StaleSecrets The number of secrets in the project that have not been updated in the last 90 days.
					StaleSecrets int `json:"staleSecrets"`
				} `json:"warnings"`
			} `json:"projects"`

			// ProjectsWithIssues The number of secret management projects in the organization with at least one issue.
			ProjectsWithIssues int `json:"projectsWithIssues"`

			// TotalProjects The total number of secret management projects in the organization.
			TotalProjects int `json:"totalProjects"`
		} `json:"projectWarnings"`
	}
}

